tool_input.old_string:
/**
 * 走查 row4：学习园地 / 新闻公告列表项不要展示「发布人 / 作者 / 来源」。
 * 后端 meta 常把发布单位拼在日期前（如「市住建局物业管理处 · 2026-10-22 · 1,580阅读」），
 * 这里在首页卡片渲染时去掉日期之前的发布单位片段，只保留时间/阅读数等。
 */
function displayMeta(meta?: string): string {
  if (!meta) return ''
  const parts = meta.split('·').map(s => s.trim()).filter(Boolean)
  if (parts.length <= 1) return meta
  // 去掉首段若它不是纯日期/时长/数字类信息（视为发布单位）
  const first = parts[0]
  const looksLikeDateOrCount = /^\d{4}[-/.]\d{1,2}[-/.]\d{1,2}/.test(first)
    || /^\d+\s*(分钟|次|阅读|学习)/.test(first)
    || /^\d[\d,]*/.test(first)
  return (looksLikeDateOrCount ? parts : parts.slice(1)).join(' · ')
}

